<script lang="ts">
	import { PUBLIC_SITE_NAME } from "$env/static/public";
	import { Constants } from "$lib";
	import API from "$lib/API";
	import ErrorComponent from "$lib/components/ErrorComponent.svelte";
	import * as Empty from "$lib/components/ui/empty";
	import { Spinner } from "$lib/components/ui/spinner";
	import UploadChapter from "$lib/components/upload/UploadChapter.svelte";
	import { signerIdentity } from "$localLibrary/publication";
	import { loadUploadAccount } from "$publicApi/upload-client";
	import { StatusCodes } from "http-status-codes";
	import { onDestroy, onMount } from "svelte";

	const { data } = $props();
	let user = $state.raw<User>();
	let isMounted = $state(false);
	let error = $state<Constants.Error.Error>();

	let lookupGeneration = 0, lookupDisposed = false;
	onDestroy(() => { lookupDisposed = true; lookupGeneration++; user = undefined; });
	$effect(() => {
		const target = data.manga?.id, actor = $signerIdentity.owner, signerGeneration = $signerIdentity.generation, generation = ++lookupGeneration;
		user = undefined; error = undefined; isMounted = false;
		if (!target || !actor) return;
		const assertLookup = () => {
			if (lookupDisposed || generation !== lookupGeneration || actor !== $signerIdentity.owner || signerGeneration !== $signerIdentity.generation || target !== data.manga?.id) throw Error("The selected upload identity or target changed");
		};
		void loadUploadAccount(assertLookup).then(account => {
			assertLookup(); user = account; isMounted = true;
		}).catch(cause => { if (!lookupDisposed && generation === lookupGeneration) error = cause instanceof Constants.Error.Error ? cause : Constants.Error.Unknown; });
	});

</script>

<svelte:head>
	{#if data.manga}
		<title>Upload: {data.manga.title} - {PUBLIC_SITE_NAME}</title>
	{:else}
		<title>Upload - {PUBLIC_SITE_NAME}</title>
	{/if}
</svelte:head>

{#if !$signerIdentity.owner}
	<section class="mx-auto max-w-270 space-y-3 p-5"><h2 class="text-xl font-medium">Connect a signing identity</h2><p>Open Public identity in Settings to create, import or connect the identity bound to your upload account. Admission and upload permissions are checked separately.</p><a class="underline" href="/settings">Open Settings</a></section>
{:else if error}
	<ErrorComponent {error} />
{:else if isMounted && data.manga && user}
	{#key data.manga.id}
		<UploadChapter manga={data.manga} {user} />
	{/key}
{:else}
	<Empty.Root>
		<Spinner class="size-10" />
	</Empty.Root>
{/if}
